/* FacturaFácil - capa de datos (localStorage) */
const Store = (() => {
  const KEY = 'facturafacil.data.v1';

  const DEFAULTS = {
    settings: {
      company: { name: '', nif: '', address: '', email: '', phone: '' },
      prefix: 'F-',
      nextNumber: 1,
      defaultIva: 21,
      daysToPay: 30
    },
    clients: [],
    invoices: []
  };

  function clone(o) { return JSON.parse(JSON.stringify(o)); }

  let data = load();

  function load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        return Object.assign(clone(DEFAULTS), parsed, {
          settings: Object.assign(clone(DEFAULTS.settings), parsed.settings || {},
            { company: Object.assign(clone(DEFAULTS.settings.company), (parsed.settings||{}).company || {}) })
        });
      }
    } catch (e) { console.warn('No se pudo leer los datos guardados', e); }
    return clone(DEFAULTS);
  }

  function persist() {
    localStorage.setItem(KEY, JSON.stringify(data));
  }

  function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

  return {
    uid,
    getSettings() { return clone(data.settings); },
    saveSettings(patch) {
      data.settings = Object.assign(data.settings, patch);
      if (patch.company) data.settings.company = Object.assign(data.settings.company, patch.company);
      persist();
      return clone(data.settings);
    },
    listClients() { return data.clients.slice().sort((a,b)=>a.name.localeCompare(b.name,'es')); },
    getClient(id) { return data.clients.find(c=>c.id===id) || null; },
    saveClient(client) {
      if (client.id) {
        const i = data.clients.findIndex(c=>c.id===client.id);
        if (i>=0) data.clients[i] = Object.assign(data.clients[i], client);
        else data.clients.push(Object.assign({id: uid()}, client));
      } else {
        client = Object.assign({id: uid()}, client);
        data.clients.push(client);
      }
      persist();
      return client;
    },
    deleteClient(id) {
      data.clients = data.clients.filter(c=>c.id!==id);
      persist();
    },
    listInvoices() { return data.invoices.slice().sort((a,b)=> (b.issueDate||'').localeCompare(a.issueDate||'') || b.number.localeCompare(a.number)); },
    getInvoice(id) { return data.invoices.find(i=>i.id===id) || null; },
    allocateNumber() {
      const n = data.settings.nextNumber;
      data.settings.nextNumber = n + 1;
      persist();
      return data.settings.prefix + String(n).padStart(4, '0');
    },
    saveInvoice(invoice) {
      if (invoice.id) {
        const i = data.invoices.findIndex(x=>x.id===invoice.id);
        if (i>=0) { data.invoices[i] = Object.assign(data.invoices[i], invoice); persist(); return data.invoices[i]; }
      }
      invoice = Object.assign({id: uid()}, invoice);
      data.invoices.push(invoice);
      persist();
      return invoice;
    },
    deleteInvoice(id) { data.invoices = data.invoices.filter(i=>i.id!==id); persist(); },
    invoiceCount() { return data.invoices.length; },
    clientCount() { return data.clients.length; }
  };
})();
```

