/* FacturaFácil - lógica de la aplicación */
(function () {
  const main = document.getElementById('main');
  const modalRoot = document.getElementById('modal-root');
  const printArea = document.getElementById('print-area');

  const IVA_OPTIONS = [0, 4, 10, 21];

  // ---------- utilidades ----------
  const money = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
  const fmtMoney = v => money.format(Number(v) || 0);
  const fmtDate = iso => { if (!iso) return '—'; const d = new Date(iso + 'T00:00:00'); return isNaN(d) ? '—' : d.toLocaleDateString('es-ES'); };
  const todayISO = () => { const d = new Date(); return [d.getFullYear(), String(d.getMonth()+1).padStart(2,'0'), String(d.getDate()).padStart(2,'0')].join('-'); };
  const addDays = (iso, days) => { const d = new Date(iso + 'T00:00:00'); d.setDate(d.getDate()+Number(days)); return [d.getFullYear(), ...].join('-'); };
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function lineBase(l) { return (Number(l.qty)||0) * (Number(l.price)||0); }
  function lineIva(l) { return lineBase(l) * (Number(l.iva)||0) / 100; }
  function invoiceTotals(inv) {
    let base = 0, tax = 0;
    (inv.lines||[]).forEach(l => { base += lineBase(l); tax += lineIva(l); });
    return { base, tax, total: base + tax };
  }
  function statusOf(inv) {
    if (inv.status === 'borrador') return 'borrador';
    if (inv.status === 'cobrada') return 'cobrada';
    return inv.dueDate && inv.dueDate < todayISO() ? 'vencida' : 'pendiente';
  }
  const STATUS_LABEL = { borrador:'Borrador', pendiente:'Pendiente', cobrada:'Cobrada', vencida:'Vencida' };
  const statusBadge = s => `<span class="badge badge-${s}">${STATUS_LABEL[s]}</span>`;

  function clientName(id) { const c = Store.getClient(id); return c ? c.name : 'Sin cliente'; }
