{"kind":"tool","id":"gsYFIHk2_-0","toolName":"write_file","input":{"path":"/c/Users/jjmax/Downloads/5-Billdin/js/store.js","instructions":"Capa de datos con persistencia en localStorage","content":"/* FacturaFácil - capa de datos (persistencia en localStorage) */
const Store = (() => {
  const KEY = 'facturafacil.data.v1';

  const DEFAULTS = {
    settings: {
      company: { name: '', nif: '', address: '', email: '', phone: '' },
      prefix: 'F-',
      nextNumber: 1,
      defaultIva: 21,
      daysToPay: 30
    },
    clients: [],
    invoices: []
  };

  const clone = o => JSON.parse(JSON.stringify(o));

  function normalize(parsed) {
    const data = Object.assign(clone(DEFAULTS), parsed || {});
    const ps = (parsed && parsed.settings) || {};
    data.settings = Object.assign(clone(DEFAULTS.settings), ps);
    data.settings.company = Object.assign(clone(DEFAULTS.settings.company), ps.company || {});
    if (!Array.isArray(data.clients)) data.clients = [];
    if (!Array.isArray(data.invoices)) data.invoices = [];
    return data;
  }

  function load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) return normalize(JSON.parse(raw));
    } catch (e) {
      console.warn('No se pudieron leer los datos guardados:', e);
    }
    return clone(DEFAULTS);
  }

  let data = load();

  function persist() {
    localStorage.setItem(KEY, JSON.stringify(data));
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  return {
    uid,

    getSettings() { return clone(data.settings); },
    saveSettings(patch) {
      const ps = patch && patch.settings ? patch.settings : patch || {};
      data.settings = Object.assign(data.settings, ps);
      if (ps.company) data.settings.company = Object.assign(data.settings.company, ps.company);
      persist();
      return clone(data.settings);
    },

    listClients() {
      return data.clients.slice().sort((a, b) => String(a.name).localeCompare(String(b.name), 'es'));
    },
    getClient(id) { return data.clients.find(c => c.id === id) || null; },
    saveClient(client) {
      if (client.id) {
        const i = data.clients.findIndex(c => c.id === client.id);
        if (i >= 0) {
          data.clients[i] = Object.assign(data.clients[i], client);
          persist();
          return data.clients[i];
        }
      }
      const saved = Object.assign({ id: uid() }, client);
      data.clients.push(saved);
      persist();
      return saved;
    },
    deleteClient(id) {
      data.clients = data.clients.filter(c => c.id !== id);
      persist();
    },

    listInvoices() {
      return data.invoices.slice().sort((a, b) =>
        String(b.issueDate || '').localeCompare(String(a.issueDate || '')) ||
        String(b.number || '').localeCompare(String(a.number || '')));
    },
    getInvoice(id) { return data.invoices.find(i => i.id === id) || null; },
    allocateNumber() {
      const n = data.settings.nextNumber;
      data.settings.nextNumber = n + 1;
      persist();
      return data.settings.prefix + String(n).padStart(4, '0');
    },
    saveInvoice(invoice) {
      if (invoice.id) {
        const i = data.invoices.findIndex(x => x.id === invoice.id);
        if (i >= 0) {
          data.invoices[i] = Object.assign(data.invoices[i], invoice);
          persist();
          return data.invoices[i];
        }
      }
      const saved = Object.assign({ id: uid() }, invoice);
      data.invoices.push(saved);
      persist();
      return saved;
    },
    deleteInvoice(id) {
      data.invoices = data.invoices.filter(i => i.id !== id);
      persist();
    },

    exportData() { return clone(data); },
    importData(obj) {
      if (!obj || typeof obj !== 'object' || !Array.isArray(obj.clients) || !Array.isArray(obj.invoices)) {
        throw new Error('el archivo no tiene un formato válido');
      }
      data = normalize(obj);
      persist();
      return clone(data);
    }
  };
})();
