const mainEl = document.getElementById('main');
const modalRoot = document.getElementById('modal-root');
const printArea = document.getElementById('print-area');

const IVA_OPTIONS = [0, 4, 10, 21];
const STATUS_LABEL = { borrador: 'Borrador', pendiente: 'Pendiente', cobrada: 'Cobrada', vencida: 'Vencida' };

/* ---------- Utilidades ---------- */
const moneyFmt = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
function fmtMoney(v) { return moneyFmt.format(Number(v) || 0); }
function pad2(n) { return String(n).padStart(2, '0'); }
function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}
function addDaysISO(iso, days) {
  const d = new Date(iso + 'T00:00:00');
  d.setDate(d.getDate() + (Number(days) || 0));
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}
function fmtDate(iso) {
  if (!iso) return '—';
  const d = new Date(iso + 'T00:00:00');
  return isNaN(d) ? '—' : d.toLocaleDateString('es-ES');
}
function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}
function lineBase(l) { return (Number(l.qty) || 0) * (Number(l.price) || 0); }
function lineTax(l) { return lineBase(l) * (Number(l.iva) || 0) / 100; }
function invoiceTotals(inv) {
  let base = 0, tax = 0;
  (inv.lines || []).forEach(l => { base += lineBase(l); tax += lineTax(l); });
  return { base, tax, total: base + tax };
}
function statusOf(inv) {
  if (inv.status === 'borrador' || inv.status === 'cobrada') return inv.status;
  return (inv.dueDate && inv.dueDate < todayISO()) ? 'vencida' : 'pendiente';
}
function badge(s) { return `<span class="badge badge-${s}">${STATUS_LABEL[s]}</span>`; }
function clientOf(id) { return Store.getClient(id); }
function clientLabel(id) { const c = clientOf(id); return c ? esc(c.name) : '—'; }

function toast(msg) {
  const root = document.getElementById('toast-root');
  const el = document.createElement('div');
  el.className = 'toast';
  el.textContent = msg;
  root.appendChild(el);
  setTimeout(() => el.remove(), 2600);
}

function newLine(iva) { return { concept: '', qty: 1, price: 0, iva: Number(iva) || 0 }; }

/* ---------- Modal genérico ---------- */
function openModal({ title, fields, onSubmit, submitLabel = 'Guardar' }) {
  modalRoot.innerHTML = `
    <div class="modal-backdrop" id="modal-backdrop">
      <form class="modal" id="modal-form">
        <h3>${esc(title)}</h3>
        <div class="modal-body">${fields}</div>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="modal-cancel">Cancelar</button>
          <button type="submit" class="btn btn-primary">${esc(submitLabel)}</button>
        </div>
      </form>
    </div>`;
  const close = () => { modalRoot.innerHTML = ''; };
  document.getElementById('modal-cancel').addEventListener('click', close);
  document.getElementById('modal-backdrop').addEventListener('click', e => {
    if (e.target.id === 'modal-backdrop') close();
  });
  document.getElementById('modal-form').addEventListener('submit', e => {
    e.preventDefault();
    const ok = onSubmit(e.target);
    if (ok !== false) close();
  });
  const first = modalRoot.querySelector('input,select,textarea');
  if (first) first.focus();
}
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') modalRoot.innerHTML = '';
});

/* ---------- Tabla de facturas (reutilizable) ---------- */
function invoiceTable(list, withActions = true) {
  const rows = list.map(inv => {
    const st = statusOf(inv);
    const actions = withActions ? `
      <div class="row-actions">
        <a class="btn btn-ghost" href="#/factura/ver/${inv.id}">Ver</a>
        <a class="btn btn-ghost" href="#/factura/edit/${inv.id}">Editar</a>
        ${st === 'pendiente' || st === 'vencida' ? `<button class="btn btn-ghost" data-pay="${inv.id}">Cobrar</button>` : ''}
        <button class="btn btn-ghost" data-dup="${inv.id}">Duplicar</button>
        <button class="btn btn-danger" data-del="${inv.id}">Eliminar</button>
      </div>` : `<div class="row-actions"><a class="btn btn-ghost" href="#/factura/ver/${inv.id}">Ver</a></div>`;
    return `
      <tr>
        <td><strong>${esc(inv.number || '—')}</strong></td>
        <td>${clientLabel(inv.clientId)}</td>
        <td>${fmtDate(inv.issueDate)}</td>
        <td>${fmtDate(inv.dueDate)}</td>
        <td class="num"><strong>${fmtMoney(invoiceTotals(inv).total)}</strong></td>
        <td>${badge(st)}</td>
        <td>${actions}</td>
      </tr>`;
  }).join('');
  return `
    <div class="table-wrap">
      <table>
        <thead>
          <tr>
            <th>Nº</th><th>Cliente</th><th>Emisión</th><th>Vencimiento</th>
            <th class="num">Total</th><th>Estado</th><th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

function bindInvoiceRowActions(scope) {
  scope.querySelectorAll('[data-pay]').forEach(btn => btn.addEventListener('click', () => {
    const inv = Store.getInvoice(btn.dataset.pay);
    if (!inv) return;
    inv.status = 'cobrada';
    inv.paidDate = todayISO();
    Store.saveInvoice(inv);
    toast('Factura marcada como cobrada');
    render();
  }));
  scope.querySelectorAll('[data-dup]').forEach(btn => btn.addEventListener('click', () => {
    const inv = Store.getInvoice(btn.dataset.dup);
    if (!inv) return;
    const copy = JSON.parse(JSON.stringify(inv));
    copy.id = null;
    copy.number = null;
    copy.status = 'borrador';
    copy.paidDate = '';
    copy.issueDate = todayISO();
    copy.dueDate = addDaysISO(todayISO(), Store.getSettings().daysToPay || 30);
    const saved = Store.saveInvoice(copy);
    toast('Factura duplicada como borrador');
    location.hash = '#/factura/edit/' + saved.id;
  }));
  scope.querySelectorAll('[data-del]').forEach(btn => btn.addEventListener('click', () => {
    const inv = Store.getInvoice(btn.dataset.del);
    if (!inv) return;
    if (!confirm(`¿Eliminar la factura ${inv.number || ''}? Esta acción no se puede deshacer.`)) return;
    Store.deleteInvoice(inv.id);
    toast('Factura eliminada');
    render();
  }));
}

/* ---------- Vista: Resumen (dashboard) ---------- */
function viewDashboard() {
  const s = Store.getSettings();
  const invoices = Store.listInvoices();
  const clients = Store.listClients();
  const year = String(new Date().getFullYear());

  let issuedY = 0, collected = 0, pending = 0, overdue = 0;
  const overdueList = [];
  invoices.forEach(inv => {
    const st = statusOf(inv);
    const total = invoiceTotals(inv).total;
    if (st !== 'borrador' && String(inv.issueDate || '').startsWith(year)) issuedY += total;
    if (st === 'cobrada') collected += total;
    else if (st === 'pendiente') pending += total;
    else if (st === 'vencida') { overdue += total; overdueList.push(inv); }
  });

  const isEmpty = !s.company.name && !clients.length && !invoices.length;
  const recent = invoices.slice(0, 5);

  mainEl.innerHTML = `
    <div class="page-head">
      <div><h1>Resumen</h1><p class="muted">Tu actividad de facturación de un vistazo.</p></div>
      <a class="btn btn-primary" href="#/factura/nueva">+ Nueva factura</a>
    </div>

    ${isEmpty ? `
      <div class="card welcome">
        <h2>¡Bienvenido a FacturaFácil! 👋</h2>
        <p>Empieza en tres pasos:</p>
        <p>1. Configura los datos de tu empresa en <a href="#/ajustes">Ajustes</a>.<br>
