           3. Crea tu primera factura con el botón <strong>+ Nueva factura</strong>.</p>
        <p class="muted">Tus datos se guardan en este navegador. Desde Ajustes puedes exportar una copia de seguridad.</p>
      </div>` : ''}

    <div class="stat-grid">
      <div class="stat"><div class="label">Facturado en ${year}</div><div class="value">${fmtMoney(issuedY)}</div></div>
      <div class="stat ok"><div class="label">Cobrado</div><div class="value">${fmtMoney(collected)}</div></div>
      <div class="stat"><div class="label">Pendiente de cobro</div><div class="value">${fmtMoney(pending)}</div></div>
      <div class="stat ${overdue > 0 ? 'danger' : ''}"><div class="label">Vencido</div><div class="value">${fmtMoney(overdue)}</div></div>
    </div>

    ${overdueList.length ? `<h2>Facturas vencidas</h2>${invoiceTable(overdueList, false)}` : ''}

    <h2>Últimas facturas</h2>
    ${recent.length ? invoiceTable(recent, false) : `
      <div class="card empty">
        <h3>Todavía no tienes facturas</h3>
        <p>Crea tu primera factura y aparecerá aquí.</p>
        <a class="btn btn-primary" href="#/factura/nueva">Crear mi primera factura</a>
      </div>`}
  `;
  bindInvoiceRowActions(mainEl);
}

