function openClientModal(id, afterSave) {
  const c = id ? Store.getClient(id) : null;
  if (!c && id) return;
  openModal({
    title: c ? 'Editar cliente' : 'Nuevo cliente',
    fields: `
      <label>Nombre / razón social * <input name="name" required value="${esc(c && c.name)}"></label>
      <label>NIF / CIF <input name="nif" value="${esc(c && c.nif)}"></label>
      <label>Email <input type="email" name="email" value="${esc(c && c.email)}"></label>
      <label>Teléfono <input name="phone" value="${esc(c && c.phone)}"></label>
      <label>Dirección <input name="address" value="${esc(c && c.address)}"></label>`,
    onSubmit(form) {
      const fd = Object.fromEntries(new FormData(form).entries());
      Object.keys(fd).forEach(k => { fd[k] = String(fd[k]).trim(); });
      if (!fd.name) { toast('El nombre es obligatorio'); return false; }
      Store.saveClient(Object.assign({}, c || {}, fd));
      toast('Cliente guardado');
      if (afterSave) afterSave();
      return true;
    }
  });
}

