        <button class="btn btn-danger" id="act-del">Eliminar</button>
      </div>
    </div>
    ${invoiceDocHTML(inv)}
  `;
  const on = (sel, fn) => { const el = document.querySelector(sel); if (el) el.addEventListener('click', fn); };
