    status: 'borrador',
    paidDate: '',
    notes: '',
    lines: [newLine(settings.defaultIva)]
  };
  if (!draft.lines || !draft.lines.length) draft.lines = [newLine(settings.defaultIva)];

  const isDraft = draft.status === 'borrador';

  mainEl.innerHTML = `
    <div class="page-head">
      <div>
        <h1>${isNew ? 'Nueva factura' : 'Editar factura ' + esc(draft.number || '')}</h1>
        <a class="link" href="${draft.id ? '#/factura/ver/' + draft.id : '#/facturas'}">← Volver</a>
      </div>
    </div>

    <form id="invoice-form" class="card form">
      <div class="form-grid">
        <label>Cliente
          <select name="clientId">
            ${clients.map(c => `<option value="${c.id}" ${c.id === draft.clientId ? 'selected' : ''}>${esc(c.name)}${c.nif ? ' · ' + esc(c.nif) : ''}</option>`).join('')}
          </select>
        </label>
        <label>Fecha de emisión <input type="date" name="issueDate" value="${esc(draft.issueDate)}"></label>
        <label>Vencimiento <input type="date" name="dueDate" value="${esc(draft.dueDate || '')}"></label>
        <label class="span-2" style="flex-direction:row;align-items:center;gap:8px">
          <input type="checkbox" name="autoDue" checked style="width:auto"> Calcular el vencimiento automáticamente (ajustes → días para el vencimiento)
        </label>
      </div>

      <h2>Conceptos</h2>
      <div class="table-wrap">
        <table class="lines-table">
          <thead>
            <tr><th>Concepto</th><th class="num">Cant.</th><th class="num">Precio (€)</th><th class="num">IVA</th><th class="num">Importe</th><th></th></tr>
          </thead>
          <tbody id="lines-body"></tbody>
        </table>
      </div>
      <div style="margin-top:12px">
        <button type="button" class="btn" id="add-line">+ Añadir concepto</button>
      </div>

      <div class="totals" id="totals"></div>

      <div style="margin-top:18px">
        <label style="display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:600;color:#475569">
          Notas (forma de pago, referencia…)
          <textarea name="notes" rows="2">${esc(draft.notes || '')}</textarea>
        </label>
      </div>

      <div class="form-actions">
        <button type="button" class="btn" id="save-btn">${isNew ? 'Guardar borrador' : 'Guardar cambios'}</button>
        ${isDraft ? `<button type="button" class="btn btn-primary" id="emit-btn">${isNew ? 'Emitir factura' : 'Emitir factura'}</button>` : ''}
        <a class="btn btn-ghost" href="${draft.id ? '#/factura/ver/' + draft.id : '#/facturas'}">Cancelar</a>
      </div>
    </form>
  `;

  const form = document.getElementById('invoice-form');
  const body = document.getElementById('lines-body');
  const totalsEl = document.getElementById('totals');
  const issueInput = form.elements.issueDate;
  const dueInput = form.elements.dueDate;
  const autoDue = form.elements.autoDue;

  function syncDueDate() {
    if (autoDue.checked && issueInput.value) {
      dueInput.value = addDaysISO(issueInput.value, settings.daysToPay || 30);
    }
  }
  issueInput.addEventListener('change', syncDueDate);
  autoDue.addEventListener('change', syncDueDate);
  if (isNew) syncDueDate();

  function renderLines() {
    body.innerHTML = draft.lines.map((l, i) => `
      <tr>
        <td><input data-i="${i}" data-f="concept" value="${esc(l.concept)}" placeholder="Servicio o producto"></td>
        <td class="num"><input class="narrow" type="number" min="0" step="any" data-i="${i}" data-f="qty" value="${Number(l.qty) || 0}"></td>
        <td class="num"><input class="narrow" type="number" min="0" step="0.01" data-i="${i}" data-f="price" value="${Number(l.price) || 0}"></td>
        <td class="num">
          <select class="narrow" data-i="${i}" data-f="iva">
            ${IVA_OPTIONS.map(o => `<option value="${o}" ${Number(l.iva) === o ? 'selected' : ''}>${o}%</option>`).join('')}
          </select>
        </td>
        <td class="num cell-amount">${fmtMoney(lineBase(l))}</td>
        <td><button type="button" class="icon-btn" data-remove="${i}" title="Quitar concepto">×</button></td>
      </tr>`).join('');
    renderTotals();
  }

  function renderTotals() {
    const t = invoiceTotals(draft);
    totalsEl.innerHTML = `
      <div><span>Base imponible</span><strong>${fmtMoney(t.base)}</strong></div>
      <div><span>IVA</span><strong>${fmtMoney(t.tax)}</strong></div>
      <div class="total"><span>Total</span><strong>${fmtMoney(t.total)}</strong></div>`;
    [...body.rows].forEach((row, i) => {
      const cell = row.querySelector('.cell-amount');
      if (cell) cell.textContent = fmtMoney(lineBase(draft.lines[i]));
    });
  }

  body.addEventListener('input', e => {
    const el = e.target;
    if (!el.dataset || !el.dataset.f) return;
    const i = Number(el.dataset.i);
    const f = el.dataset.f;
    draft.lines[i][f] = f === 'concept' ? el.value : Number(el.value);
    renderTotals();
  });
  body.addEventListener('change', e => {
    const el = e.target;
    if (!el.dataset || !el.dataset.f || el.dataset.f !== 'iva') return;
    draft.lines[Number(el.dataset.i)].iva = Number(el.value);
    renderTotals();
  });
  body.addEventListener('click', e => {
    const btn = e.target.closest('[data-remove]');
    if (!btn) return;
    const i = Number(btn.dataset.remove);
    if (draft.lines.length === 1) draft.lines = [newLine(settings.defaultIva)];
    else draft.lines.splice(i, 1);
    renderLines();
  });
  document.getElementById('add-line').addEventListener('click', () => {
    draft.lines.push(newLine(settings.defaultIva));
    renderLines();
    const inputs = body.querySelectorAll('[data-f="concept"]');
    inputs[inputs.length - 1].focus();
  });

  function collect() {
    draft.clientId = form.elements.clientId.value;
    draft.issueDate = form.elements.issueDate.value;
    draft.dueDate = form.elements.dueDate.value;
    draft.notes = form.elements.notes.value.trim();
    draft.lines = draft.lines.filter(l => String(l.concept).trim() !== '' || lineBase(l) !== 0);
  }

  function persistInvoice(status) {
    collect();
    if (!draft.clientId) { toast('Selecciona un cliente'); return; }
    if (!draft.issueDate) { toast('Indica la fecha de emisión'); return; }
    if (!draft.lines.length) { toast('Añade al menos un concepto'); return; }
    if (status) draft.status = status;
    if (!draft.number) draft.number = Store.allocateNumber();
    if (draft.status === 'cobrada' && !draft.paidDate) draft.paidDate = todayISO();
    const saved = Store.saveInvoice(draft);
    toast('Factura guardada');
    location.hash = '#/factura/ver/' + saved.id;
  }

  document.getElementById('save-btn').addEventListener('click', () => {
    persistInvoice(isNew ? 'borrador' : null);
  });
  const emitBtn = document.getElementById('emit-btn');
  if (emitBtn) emitBtn.addEventListener('click', () => persistInvoice('pendiente'));

  renderLines();
  if (isNew) {
    const concept = body.querySelector('[data-f="concept"]');
    if (concept) concept.focus();
  }
}

/* ---------- Vista: Ajustes ---------- */
function viewSettings() {
  const s = Store.getSettings();
  const co = s.company;
  mainEl.innerHTML = `
    <div class="page-head"><div><h1>Ajustes</h1><p class="muted">Datos de tu empresa, numeración e impuestos.</p></div></div>

    <form id="settings-form" class="card form">
      <h2 style="margin-top:0">Datos de tu empresa</h2>
      <p class="muted" style="margin-top:-6px">Aparecerán en el encabezado de todas tus facturas.</p>
      <div class="form-grid">
        <label>Nombre / razón social * <input name="name" value="${esc(co.name)}"></label>
        <label>NIF / CIF <input name="nif" value="${esc(co.nif)}"></label>
        <label>Email <input type="email" name="email" value="${esc(co.email)}"></label>
        <label>Teléfono <input name="phone" value="${esc(co.phone)}"></label>
        <label class="span-2">Dirección <input name="address" value="${esc(co.address)}"></label>
      </div>

      <h2>Numeración y impuestos</h2>
      <div class="form-grid">
        <label>Prefijo de numeración <input name="prefix" value="${esc(s.prefix)}"></label>
        <label>Siguiente número <input type="number" min="1" name="nextNumber" value="${Number(s.nextNumber) || 1}"></label>
        <label>IVA por defecto (%) <input type="number" min="0" max="100" name="defaultIva" value="${Number(s.defaultIva) || 0}"></label>
        <label>Días para el vencimiento <input type="number" min="0" name="daysToPay" value="${Number(s.daysToPay) || 0}"></label>
      </div>

      <div class="form-actions">
        <button type="submit" class="btn btn-primary">Guardar ajustes</button>
      </div>
    </form>

    <div class="card" style="margin-top:22px">
      <h2 style="margin-top:0">Copia de seguridad</h2>
      <p class="muted" style="margin-top:-6px">Exporta todos tus datos (clientes, facturas y ajustes) a un archivo JSON, o restáuralos desde una copia.</p>
      <div class="form-actions">
        <button class="btn" id="export-btn">Exportar datos</button>
        <label class="btn" for="import-file" style="cursor:pointer">Importar copia</label>
        <input type="file" id="import-file" accept="application/json,.json" hidden>
      </div>
    </div>
  `;

  document.getElementById('settings-form').addEventListener('submit', e => {
    e.preventDefault();
    const f = e.target;
    const name = f.elements.name.value.trim();
    if (!name) { toast('El nombre de la empresa es obligatorio'); return; }
    Store.saveSettings({
      company: {
        name,
        nif: f.elements.nif.value.trim(),
        email: f.elements.email.value.trim(),
        phone: f.elements.phone.value.trim(),
        address: f.elements.address.value.trim()
      },
      prefix: f.elements.prefix.value.trim() || 'F-',
      nextNumber: Math.max(1, Number(f.elements.nextNumber.value) || 1),
      defaultIva: Math.min(100, Math.max(0, Number(f.elements.defaultIva.value) || 0)),
      daysToPay: Math.max(0, Number(f.elements.daysToPay.value) || 0)
    });
    document.getElementById('company-name').textContent = name;
    toast('Ajustes guardados');
  });

  document.getElementById('export-btn').addEventListener('click', () => {
    const blob = new Blob([JSON.stringify(Store.exportData(), null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'facturafacil-copia-' + todayISO() + '.json';
    a.click();
    URL.revokeObjectURL(a.href);
    toast('Copia de seguridad exportada');
  });

  document.getElementById('import-file').addEventListener('change', e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        Store.importData(JSON.parse(reader.result));
        toast('Copia importada correctamente');
        render();
      } catch (err) {
        toast('No se pudo importar: ' + err.message);
      }
    };
    reader.readAsText(file);
  });
}

/* ---------- Enrutador ---------- */
function updateNav(hash) {
  document.querySelectorAll('[data-nav]').forEach(a => {
    const target = a.dataset.nav;
    const active = target === hash || (hash.startsWith('#/factura') && target === '#/facturas');
    a.classList.toggle('active', active);
  });
}

function render() {
  const hash = location.hash || '#/dashboard';
  updateNav(hash);
  window.scrollTo(0, 0);

  if (hash.startsWith('#/factura/ver/')) return viewInvoiceDetail(hash.split('/')[3]);
  if (hash.startsWith('#/factura/edit/')) {
    const inv = Store.getInvoice(hash.split('/')[3]);
    if (inv) return viewInvoiceForm(inv);
    location.hash = '#/facturas';
    return;
  }
  if (hash === '#/factura/nueva') return viewInvoiceForm(null);

  switch (hash) {
    case '#/clientes': return viewClients();
    case '#/facturas': return viewInvoices();
    case '#/ajustes': return viewSettings();
    default: return viewDashboard();
  }
}

window.addEventListener('hashchange', render);
document.getElementById('company-name').textContent = Store.getSettings().company.name || '';
render();
